def shipping_zone(country_code):
    if country_code == "US":
        return 1
    if country_code in ("CA", "MX"):
        return 2
    return 3


def shipping_cost(weight_kg, zone):
    bases = {1: 5.0, 2: 12.0, 3: 25.0}
    base = bases[zone]
    return round(base + 0.8 * weight_kg, 2)


def is_oversize(l, w, h):
    return l > 120 or w > 120 or h > 120 or (l + w + h) > 300

import re


def bulk_discount(qty):
    if qty >= 100:
        return 0.15
    if qty >= 20:
        return 0.05
    return 0.0


def line_total(unit_price, qty):
    return round(unit_price * qty * (1 - bulk_discount(qty)), 2)


_SKU_RE = re.compile(r"^([A-Z]{2,4})-(\d{4})-([A-Za-z])$")


def parse_sku(s):
    if not isinstance(s, str):
        raise ValueError("invalid SKU: %r" % (s,))
    m = _SKU_RE.match(s)
    if not m:
        raise ValueError("invalid SKU: %r" % (s,))
    return {"category": m.group(1), "number": int(m.group(2)), "variant": m.group(3)}

